typedef enum upng_color {
        LWS_UPNG_LUM            = 0,
        LWS_UPNG_RGB            = 2,
        LWS_UPNG_LUMA           = 4,
        LWS_UPNG_RGBA           = 6
} upng_color;

struct upng_unfline {
        uint8_t                 *recon;
        const uint8_t           *scanline;
        const uint8_t           *precon;
        uint8_t                 filterType;
        unsigned int            bypp;
        unsigned int            bypl;

        const uint8_t           *in;
        uint8_t                 *lines;
        unsigned int            bpp;

        unsigned int            y;
        unsigned long           diff;
        unsigned long           ibp;
        unsigned long           sp;

        char                    padded;
        char                    alt;
};

typedef enum {
        UOF_MAGIC,
        UOF_SKIP,
        UOF_TYPE4,
        UOF_WIDTH4,
        UOF_HEIGHT4,
        UOF_CDEPTH,
        UOF_CTYPE,
        UOF_ONLY_ZERO3,
        UOF_SKIP4,

        UOF_CHUNK_LEN,
        UOF_CHUNK_TYPE,
        UOF_INSIDE,

        UOF_SKIP_CHUNK_LEN,
} upng_outer_framing_t;



struct lws_upng_t {
        struct upng_unfline     u;
        inflator_ctx_t          inf;

        unsigned int            width;
        unsigned int            height;

        upng_color              color_type;
        unsigned int            color_depth;
        lws_upng_format_t       format;

        const uint8_t           *chunk;

        int                     sctr;
        uint32_t                acc;

        uint32_t                chunklen;
        uint32_t                ctype;

        upng_outer_framing_t    of;

        uint8_t                 no_more_input;
        char                    hold_at_metadata;
};

